Translate("deDE", "durotar", {
	title = "Durotar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Durotar ist die Heimat der {link:orcs}Orcs{/link}, ein rotes und zerklüftetes Land an der Ostküste von {link:kalimdor}Kalimdor{/link}. Sein Boden ist rissig und trocken, seine Schluchten sind scharfkantig, und die Sonne brennt gnadenlos auf es herab. Die Orcs wählten es gern, denn seine raue Schönheit erinnert sie an die Welt, die sie verloren. Hier hat der Kriegshäuptling {link:thrall}Thrall{/link} seine {link:capital-city}Hauptstadt{/link} {link:orgrimmar}Orgrimmar{/link} errichtet, und hier werden die Jungen der {link:horde}Horde{/link} geprüft, bevor man sie in die Welt hinausschickt. Es ist ein Land, das nur dem Namen nach in Frieden lebt. Feinde beobachten es vom Meer, aus den Schluchten und aus den Schatten seiner eigenen Höhlen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Bevor die {link:orcs}Orcs{/link} kamen, zählte man diese Lande zum {link:the-barrens}Brachland{/link}, und die {link:quilboar}Stacheleber{/link} vom {link:razormane-quilboar}Stamm der Grimmhauer{/link} streiften frei umher. Nach der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} führte {link:thrall}Thrall{/link} sein Volk nach Osten an die Küste und beanspruchte das Land zwischen dem Südstrom und dem Meer. Er nannte es Durotar, zu Ehren seines Vaters Durotan, des Häuptlings des Frostwolfklans. Die {link:tauren}Tauren{/link} und die {link:darkspear-trolls}Trolle der Darkspear{/link} liehen der neuen Nation ihre Stärke, und die Orcs vertrieben die Grimmhauer aus allen Teilen des Landes bis auf dessen westliche Ränder.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Durotar ist das Herz der neuen {link:horde}Horde{/link}. Doch sein Frieden ist dünn. Die {link:humans}Menschen{/link} von {link:kul-tiras}Kul Tiras{/link} halten noch immer die Ruinen von {link:tiragarde-keep}Burg Tiragarde{/link} an der Ostküste. Der Hexendoktor {link:zalazane}Zalazane{/link} beherrscht die Echoinseln mit dunklem Voodoo. Die {link:razormane-quilboar}Grimmhauer{/link} drängen von Westen heran, die {link:kolkar-village}Kolkar{/link}-{link:centaurs}Zentauren{/link} schmieden in ihrer Klippe Ränke, und die Staubwind-{link:harpies}Harpyien{/link} machen Jagd auf die Karawanen. Am schlimmsten ist, dass sich die Kultisten der {link:burning-blade}Burning Blade{/link} in den Höhlen Durotars verbergen, nahe den Toren der {link:capital-city}Hauptstadt{/link} selbst. In letzter Zeit hat man sogar {link:naga}Naga{/link} an der Nordküste gesehen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:orcs}Orcs{/link}.{/b} Sie bestellen den harten Boden, halten Wache vom {link:razor-hill}Klingenhügel{/link} aus und bilden ihre Jungen im Tal der Prüfungen aus.
• {b}Die {link:darkspear-trolls}Trolle der Darkspear{/link}.{/b} Von ihren Inseln vertrieben, haben sie an der Südküste ein Fischerdorf gebaut und warten auf den Tag, an dem sie heimkehren können.
• {b}Die Goblins.{/b} Händler aus {link:ratchet}Ratchet{/link} lassen Karawanen über die Straßen ziehen.
• {b}Die {link:razormane-quilboar}Stacheleber der Grimmhauer{/link}.{/b} Sie klammern sich an ihre Dornenlager im Westen und schwören, das Land zurückzunehmen.
• {b}Die {link:humans}Menschen{/link} von {link:kul-tiras}Kul Tiras{/link}.{/b} Seeleute und Marinesoldaten, die dem Andenken ihres toten Admirals dienen.
• {b}Die Burning Blade.{/b} Dämonenanbeter, die sich in den Höhlen verbergen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Landung.{/b} Nach dem Krieg gegen die {link:burning-legion}Brennende Legion{/link} erbauten die {link:orcs}Orcs{/link} {link:orgrimmar}Orgrimmar{/link} und begannen, das Land ringsum zu zähmen.
• {b}Der Krieg des Admirals.{/b} Bald darauf segelte Großadmiral {link:daelin-proudmoore}Daelin Proudmoore{/link} mit einer großen Flotte von {link:kul-tiras}Kul Tiras{/link} aus, entschlossen, den Orcs ein Ende zu machen. Seine Männer errichteten {link:tiragarde-keep}Burg Tiragarde{/link} an der Küste. Die Burg fiel, und der Admiral selbst starb vor den Mauern von {link:theramore-isle}Theramore{/link}.
• {b}Der Verräter der Inseln.{/b} Die {link:darkspear-trolls}Darkspear{/link} ließen sich auf den Echoinseln nieder, doch einer ihrer eigenen Hexendoktoren, {link:zalazane}Zalazane{/link}, wandte seine Magie gegen sie und trieb die freien {link:trolls}Trolle{/link} aufs Festland.]=],
		},
		{
			title = "Überlieferungen des roten Landes",
			text = [=[• Angehende Schamanen der {link:horde}Horde{/link} trinken am {link:spirit-rock}Geisterfelsen{/link}, hoch über dem Tal der Prüfungen, einen heiligen Trank namens Sapta, und dort treten sie vor den Geist der Erde.
• Die Trümmer von Proudmoores Flotte liegen noch in den Untiefen östlich von {link:tiragarde-keep}Burg Tiragarde{/link}. Die {link:orcs}Orcs{/link} vom {link:razor-hill}Klingenhügel{/link} schicken Schwimmer aus, um sie nach Werkzeugen der {link:humans}Menschen{/link} zu durchsuchen.
• Eine Mutter auf Tor'krens Hof wartete viele Tage auf ihren Sohn, der ausgezogen war, um die Krokilisken des Südstroms zu jagen. Er kam nicht zurück.]=],
		},
	},
})

Translate("deDE", "valley-of-trials", {
	title = "Das Tal der Prüfungen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Tal der Prüfungen liegt im Südwesten von {link:durotar}Durotar{/link}, umschlossen von roten Klippen. Es ist die Bewährungsstätte der {link:horde}Horde{/link}. Junge {link:orcs}Orcs{/link} und {link:trolls}Trolle{/link} kommen hierher, um sich ihren ersten Feinden zu stellen: den Ebern des Talbodens, den Skorpiden der nördlichen Hänge und einem ungeheuren Skorpid namens Sarkoth. Die Ausbilder der Horde haben ihr Lager in einer Höhle, die als der Höhlenbau bekannt ist. Peons fällen die wenigen Bäume des Tals für Bauholz, wenn sie nicht gerade schlafen. In letzter Zeit ist {link:stranglethorn-vale}das Tal{/link} gefährlicher geworden, denn die Burning Blade hat in den Höhlen seiner Nordwand einen Koven eingerichtet.]=],
		},
	},
})

Translate("deDE", "burning-blade-coven", {
	title = "Koven der Burning Blade",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Koven der Burning Blade ist eine Höhle in den Klippen nördlich des Tals der Prüfungen. Einst untersuchten Bergleute sie nach Erz. Nun haben die Kultisten der {link:burning-blade}Burning Blade{/link} sie in Besitz genommen, und ihre kleinen Dämonen, die üblen Vertrauten, quellen aus ihrem Eingang ins Tal. Tief drinnen, zwischen Kammern mit fallendem Wasser, bewacht der Hexenmeister {link:yarrog-baneshadow}Yarrog Baneshadow{/link} ein Medaillon von dunkler Macht. Der Koven ist klein, doch seine Nähe zur Bewährungsstätte der {link:horde}Horde{/link} ist eine Warnung, dass der Kult weiter reicht, als irgendjemandem lieb ist.]=],
		},
	},
})

Translate("deDE", "spirit-rock", {
	title = "Geisterfelsen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Geisterfelsen steht in den Hügeln hoch über dem Tal der Prüfungen, am Ende eines schmalen Pfades, der Verborgener Pfad genannt wird. Er ist den Schamanen der {link:horde}Horde{/link} heiliger Boden. Hier trinken die Jungen, die den Pfad des Schamanen gehen wollen, die Sapta, einen Trank, der den Geist an die {link:elements}Elemente{/link} bindet, und hier sehen sie den Geist der Erde zum ersten Mal mit eigenen Augen. Der Ritus muss an einem heiligen Ort vollzogen werden und nirgendwo sonst. Wenige, die keine Schamanen sind, steigen je den Verborgenen Pfad hinauf.]=],
		},
	},
})

Translate("deDE", "razor-hill", {
	title = "Klingenhügel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Klingenhügel ist die Wegkreuzung Durotars. Seine Straßen führen nach Norden nach {link:orgrimmar}Orgrimmar{/link}, nach Süden zum Tal der Prüfungen und nach {link:sen-jin-village}Sen'jin{/link} und nach Westen über den Fluss ins {link:the-barrens}Brachland{/link}. Es ist eine Stadt der Soldaten. Von seiner Kaserne aus befehligt {link:gar-thok}Gar'Thok{/link} die Verteidigung des Landes, und {link:orgnil-soulscar}Orgnil Soulscar{/link} jagt die Kultisten der Burning Blade. Ein alter Krieger hält auf dem Wachturm über der Stadt ein Signalhorn bereit. Er bläst es seltener als früher, und er ist froh darüber.]=],
		},
	},
})

Translate("deDE", "sen-jin-village", {
	title = "Sen'jin",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sen'jin ist die Heimat der freien {link:darkspear-trolls}Darkspear{/link} an der Südküste von {link:durotar}Durotar{/link}. Die {link:trolls}Trolle{/link} erbauten das Dorf, nachdem sie von den Echoinseln vertrieben worden waren, und sie benannten es nach Sen'jin, dem Häuptling, der sein Leben gab, damit sein Volk den {link:orcs}Orcs{/link} in ein neues Land folgen konnte. Es ist ein Dorf aus Hütten und Fischerstegen. Seine Ältesten sind Hexendoktoren und Alchemisten, seine Jungen sind Jäger, und seine Raptorenhüter ziehen Tiere von den wilden Inseln auf. Von seinem Ufer aus können die Trolle die Inseln sehen, die sie verloren haben.]=],
		},
	},
})

Translate("deDE", "echo-isles", {
	title = "Die Echoinseln",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Echoinseln liegen vor der Südostküste von {link:durotar}Durotar{/link}. Sie sollten die neue Heimat der {link:darkspear-trolls}Darkspear{/link} werden. Nun gehören sie dem Hexendoktor {link:zalazane}Zalazane{/link}, der die {link:trolls}Trolle{/link} der Inseln mit seinen Flüchen in Knechtschaft hält. Seine Sklaven wandern zwischen den Hütten umher, und seine Ju-Ju-Haufen verderben den Fluss der Magie im ganzen Land. Blutkrallenraptoren und gestreifte Tiger jagen im Dschungel. Auf der größten Insel hält ein Kreis aus Schädeln die gefangenen Geister von Trollen, die ihm trotzten.]=],
		},
	},
})

Translate("deDE", "tiragarde-keep", {
	title = "Burg Tiragarde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Tiragarde steht an der Ostküste von {link:durotar}Durotar{/link}. Die Seeleute von Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} errichteten sie, als ihre Flotte kam, um die {link:horde}Horde{/link} zu vernichten. Die {link:orcs}Orcs{/link} nahmen die Burg und brachen ihre Mauern. Doch nach dem Tod des Admirals kehrte eine Reservetruppe unter {link:lieutenant-benedict}Leutnant Benedict{/link} zurück und befestigte die Ruinen aufs Neue. Die Marinesoldaten von {link:kul-tiras}Kul Tiras{/link} lassen dort noch immer ihr Banner wehen. In den Trümmern um die Burg liegen die Waffen von Orcs, die beim ersten Sturm fielen, und ihre Verwandten wollen sie geehrt sehen.]=],
		},
	},
})

Translate("deDE", "skull-rock", {
	title = "Die Knochenhöhle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Knochenhöhle ist eine Höhle in den Bergen östlich der Tore von {link:orgrimmar}Orgrimmar{/link}. Sie ist ein Schlupfwinkel der {link:burning-blade}Burning Blade{/link}. Die Kultisten darin vollziehen üble Riten und verbrennen ihr eigenes Fleisch mit sengenden Halsbändern, die sie an dämonische Macht binden. Ihr Meister in der Höhle ist der Hexenmeister {link:gazz-uz}Gazz'uz{/link}, der einer Stimme gehorcht, die durch einen Anhänger aus brennendem Schatten spricht. Dass der Kult sich so nahe an den Mauern des Kriegshäuptlings verbergen kann, beunruhigt jeden Soldaten der {link:horde}Horde{/link}.]=],
		},
	},
})

Translate("deDE", "drygulch-ravine", {
	title = "Staubwindklamm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Klingenschlucht schneidet durch {link:razorfen-downs}die Hügel{/link} zwischen {link:razor-hill}Klingenhügel{/link} und {link:orgrimmar}Orgrimmar{/link}, und durch eine Höhle an ihrer Ostseite erreicht man die verborgene Klamm der Staubwindklamm. Beide gehören den Staubwind-{link:harpies}Harpyien{/link}. Sie stoßen auf die Goblinkarawanen der Straße herab, tragen ihre Waren davon und horten sie in ihren Nestern auf den Klippen. Die Stärksten des Schwarms bewachen ihre Eier in der Klamm. Einige der Hexen der Harpyien haben begonnen, mit einer seltsamen Sturmmagie zu spielen.]=],
		},
	},
})

Translate("deDE", "thunder-ridge", {
	title = "Donnergrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Donnergrat ist eine bewaldete Schlucht im Nordwesten von {link:durotar}Durotar{/link}, südlich von {link:orgrimmar}Orgrimmar{/link}. Er trägt seinen Namen nach den Donnerechsen, die ihn durchstreifen, großen Tieren, deren Körper eine Ladung Blitz in sich tragen. Der Goblinhexenmeister Fizzle Darkstorm hat dort mit Kultisten der Burning Blade ein Lager aufgeschlagen, und sie säen Chaos zwischen den Bäumen. Die {link:orcs}Orcs{/link} jagen die Echsen wegen ihrer Häute, mit denen die Dächer der wachsenden {link:capital-city}Hauptstadt{/link} ausgekleidet werden. Die mächtigste von ihnen heißt Halikor, und ihr Huf ist eine Trophäe, mit der man prahlen kann.]=],
		},
	},
})

Translate("deDE", "kolkar-crag", {
	title = "Kolkarklippe",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kolkarklippe ist eine felsige Schlucht im Süden von {link:durotar}Durotar{/link}, westlich von {link:sen-jin-village}Sen'jin{/link}. Die {link:kolkar-village}Kolkar{/link}-{link:centaurs}Zentauren{/link} haben sie zu ihrem Lager gemacht. Sie fallen bei Nacht ein, und ihr Kriegsherr Kolkanis hat Pläne entworfen, um gegen die {link:orcs}Orcs{/link} und {link:trolls}Trolle{/link} des Landes loszuschlagen. Ein Trollspäher der {link:horde}Horde{/link} schlich sich einst in die Klippe und las diese Pläne mit eigenen Augen. Andere, die versuchten, die Klippe allein auszukundschaften, kamen nicht immer wieder heraus.]=],
		},
	},
})

Translate("deDE", "razormane-grounds", {
	title = "Revier der Grimmhauer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Revier der Grimmhauer liegt im Westen von {link:durotar}Durotar{/link}, wo das Land zum Südstrom abfällt. Hier haben die {link:quilboar}Stacheleber{/link} vom {link:razormane-quilboar}Stamm der Grimmhauer{/link} ihre Dornenlager. Sie hielten einen großen Teil Durotars, bevor die {link:orcs}Orcs{/link} kamen, und sie haben seinen Verlust nie hingenommen. Abgenagte Knochen bedecken den Boden um ihre Dornen. Ihre Geomanten rufen die Erde an, und ihre Kampfwachen verteidigen die Lager mit einer Wut, die aus verletztem Stolz geboren ist. Die Orcs von {link:razor-hill}Klingenhügel{/link} haben geschworen, sie aus Durotar zu vertreiben, und danach vielleicht aus {link:kalimdor}Kalimdor{/link}.]=],
		},
	},
})

Translate("deDE", "darkspear-islands", {
	title = "Darkspear Islands",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Darkspear Islands liegen vor der Küste von {link:durotar}Durotar{/link}, gepeitscht von den Stürmen der offenen See. Die {link:trolls}Trolle{/link} halten sie für heilig, denn ihre Geister sind dort stark, und die {link:darkspear-trolls}Darkspear{/link} versammeln sich auf ihnen zu ihren Zeremonien. Nun sucht die {link:alliance}Allianz{/link} auf den Inseln einen Brückenkopf, nahe den Ufern der Heimat der {link:orcs}Orcs{/link}. Die Darkspear und ihre Verbündeten der {link:horde}Horde{/link} werden sie nicht bleiben lassen. Zwischen Ruinen, einem Lager, einem alten Turm und einer Bucht voller Schiffswracks kämpfen die beiden Seiten um die Herrschaft über die Inseln und um ein heiliges Relikt des Stammes.]=],
		},
	},
})

Translate("deDE", "kaltunk", {
	title = "Kaltunk",
	subtitle = "Empfänger der Rekruten",
	found = "Der Höhlenbau im Tal der Prüfungen",
	hint = [=[Sprecht mit dem Orc, der die jungen Rekruten im Tal der Prüfungen empfängt.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kaltunk empfängt die jungen {link:orcs}Orcs{/link} und {link:trolls}Trolle{/link}, die im Tal der Prüfungen mündig werden. Er mustert jeden mit kritischem Blick und breitem Grinsen. Er weiß, dass jeder Rekrut davon träumt, am ersten Tag einen Drachen zu erwürgen, und es bereitet ihm Vergnügen, ihnen zu sagen, sie sollten mit etwas Kleinerem anfangen. Dann lacht er und schickt sie zum Höhlenbau.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kaltunk ist die erste Stimme der {link:horde}Horde{/link}, die viele ihrer Jungen je hören. Er ist derjenige, der ihnen sagt, dass sie endlich alt genug sind, um für den Kriegshäuptling zu kämpfen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt jeden neuen Rekruten zu {link:gornek}Gornek{/link} im Höhlenbau.]=],
		},
	},
	mentions = {
		{ text = "Euer Platz in der Welt" },
	},
	bonds = {
		{ id = "gornek", name = "Gornek", note = "empfängt seine Rekruten" },
	},
})

Translate("deDE", "gornek", {
	title = "Gornek",
	subtitle = "Meister des Höhlenbaus",
	found = "Der Höhlenbau im Tal der Prüfungen",
	hint = [=[Sprecht mit dem Orc, der im Höhlenbau die ersten Prüfungen zuteilt.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gornek teilt die Prüfungen des Tals zu. Er ist mürrisch und schwer zufriedenzustellen, und er begrüßt jeden Rekruten, als sei die {link:horde}Horde{/link} wahrlich tief gesunken, ihm solches Material zu schicken. Doch er beobachtet sie genau. Er schickt sie zuerst gegen die Eber des Tals und dann gegen seine Skorpide, und er lehrt, dass selbst der kleinste Feind den Tod bringen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gornek macht aus den Jungen Krieger der {link:horde}Horde{/link}. Sein Lob ist selten, und man erinnert sich daran.]=],
		},
		{
			title = "Taten",
			text = [=[• Er prüft Rekruten an den gefleckten Ebern und den Skorpiden des Tals.
• Er schickt dem verwundeten Troll {link:hana-zua}Hana'zua{/link} Hilfe.
• Er lässt die zurückgelassenen Waffen gescheiterter Rekruten einsammeln und dem Schmied zurückgeben.]=],
		},
	},
	mentions = {
		{ text = "Zähne zeigen" },
		{ text = "Der Stich des Skorpids" },
		{ text = "Sarkoth, wie {link:hana-zua}Hana'zua{/link} es erzählt" },
		{ text = "Verirrte Waffen" },
	},
	bonds = {
		{ id = "kaltunk", name = "Kaltunk", note = "schickt ihm Rekruten" },
		{ id = "zureetha-fargaze", name = "Zureetha Fargaze", note = "teilt sein Lager" },
		{ id = "hana-zua", name = "Hana'zua", note = "der verwundete Troll, dem er hilft" },
	},
})

Translate("deDE", "zureetha-fargaze", {
	title = "Zureetha Fargaze",
	subtitle = "Seherin des Tals",
	found = "Vor dem Höhlenbau im Tal der Prüfungen",
	hint = [=[Sprecht mit der Orcfrau, die die Zeichen im Tal der Prüfungen deutet.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zureetha Fargaze wurde ins Tal der Prüfungen geschickt, um seine Rekruten zu leiten. Stattdessen fand sie eine Verderbnis. Durch ihre Weissagungen erfuhr sie, dass die {link:burning-blade}Burning Blade{/link} in den Höhlen des Tals einen Koven eingerichtet hatte und dass darin ein Gegenstand von dunkler Macht verborgen lag. Sie fürchtet, dass er nur der Vorbote eines größeren Übels ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Zureetha ist die Erste in {link:durotar}Durotar{/link}, die den Schatten der Burning Blade sieht, und sie sendet Nachricht davon durch das ganze Land.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Rekruten gegen die üblen Vertrauten des Kovens.
• Sie lässt den Kultisten das Medaillon der Burning Blade abnehmen.
• Sie schickt ihren Bericht an {link:master-gadrin}Meister Gadrin{/link} in {link:sen-jin-village}Sen'jin{/link}.]=],
		},
	},
	mentions = {
		{ text = "Üble Vertraute" },
		{ text = "Das Medaillon der Burning Blade" },
		{ text = "Bericht nach {link:sen-jin-village}Sen'jin{/link}" },
	},
	bonds = {
		{ id = "yarrog-baneshadow", name = "Yarrog Baneshadow", note = "verwahrte das Medaillon" },
		{ id = "master-gadrin", name = "Meister Gadrin", note = "erhält ihren Bericht" },
		{ id = "gornek", name = "Gornek", note = "teilt ihr Lager" },
	},
})

Translate("deDE", "hana-zua", {
	title = "Hana'zua",
	subtitle = "Verwundeter Jäger der Darkspear",
	found = "Die Hochebene südlich des Höhlenbaus",
	hint = [=[Findet den verwundeten Troll, der auf der Hochebene südlich des Höhlenbaus liegt.]=],
	allegiance = "Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hana'zua ist ein junger Troll, der im Tal der Prüfungen Skorpide jagen ging und einen fand, der weit größer war als die übrigen. Er versetzte dem Tier einen schweren Schlag auf die Schere, doch sein Stachel schnitt ihm tief in die Brust. Er liegt verwundet auf der Hochebene, zu schwach, um zum Höhlenbau zurückzugehen, und mehr um seine Ehre besorgt als um seine Wunde. Wenn er sterben muss, will er wenigstens wissen, dass sein Feind zuerst starb.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hana'zua zeigt den Stolz der {link:darkspear-trolls}Darkspear{/link}. Er bittet um Hilfe, nicht um sein Leben zu retten, sondern um seinen Feind erschlagen zu sehen.]=],
