	hint = "Sprecht mit dem Orc, der Klingenhügel befehligt.",
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gar'Thok befehligt {link:razor-hill}Klingenhügel{/link} und die Verteidigung des mittleren {link:durotar}Durotar{/link}. Er diente der {link:horde}Horde{/link}, als die {link:orcs}Orcs{/link} zuerst nach {link:kalimdor}Kalimdor{/link} kamen, und er sah die Seeleute von {link:kul-tiras}Kul Tiras{/link} über seinen Außenposten herfallen und seine Männer niedermetzeln. Er traut keinem {link:humans}Menschen{/link}. Er will die {link:razormane-quilboar}Grimmhauer{/link} aus ihren letzten {link:camping}Lagern{/link} und die Kul Tiraner aus den Ruinen von {link:tiragarde-keep}Burg Tiragarde{/link} vertreiben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gar'Thok ist der Schild der Heimat der {link:orcs}Orcs{/link}. Seine Befehle halten die Feinde Durotars in Schach, während die {link:horde}Horde{/link} baut.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Krieger gegen {link:lieutenant-benedict}Leutnant Benedict{/link} und die Männer von {link:tiragarde-keep}Burg Tiragarde{/link}.
• Er befiehlt, die {link:razormane-quilboar}Grimmhauer{/link} aus ihren Dornenlagern zu vertreiben.
• Er lässt das Wrack von Proudmoores Flotte nach Werkzeugen der {link:humans}Menschen{/link} durchsuchen.
• Er bringt die Befehle des toten Admirals nach {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Bezwingt die Verräter" },
		{ text = "Übergriffe" },
		{ text = "Aus den Trümmern..." },
		{ text = "Die Befehle des Admirals" },
		{
			text = [=[Beine in die Hand nehmen, Nachricht aus {link:sen-jin-village}Sen'jin{/link}]=],
		},
	},
	bonds = {
		{ id = "lieutenant-benedict", name = "Leutnant Benedict", note = "sein Feind" },
		{ id = "orgnil-soulscar", name = "Orgnil Soulscar", note = "dient an seiner Seite" },
		{ id = "vol-jin", name = "Vol'jin", note = "erhält seine Warnung" },
	},
})

Translate("deDE", "orgnil-soulscar", {
	title = "Orgnil Soulscar",
	subtitle = "Jäger der Burning Blade",
	found = "Klingenhügel",
	hint = [=[Sprecht mit dem Orc von Klingenhügel, der die Feinde im Inneren jagt.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Orgnil Soulscar wahrt den Frieden Durotars gegen seine verborgenen Feinde. Seine Beute ist die {link:burning-blade}Burning Blade{/link}, und er verfolgt sie ohne Gnade. Er hat ihre Kultisten bis zum {link:thunder-ridge}Donnergrat{/link} und zur Knochenhöhle aufgespürt, und er wird nicht ruhen, solange auch nur einer von ihnen im Land bleibt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Orgnil ist der Jäger des Kriegshäuptlings auf dem Land. Jeder Bericht über den Kult in {link:durotar}Durotar{/link} endet auf seinem Tisch.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Krieger aus, um den Goblinhexenmeister Fizzle Darkstorm am {link:thunder-ridge}Donnergrat{/link} zu erschlagen.
• Er schickt sie zum Schamanen {link:margoz}Margoz{/link}, um von der Knochenhöhle zu erfahren.]=],
		},
	},
	chapters = {
		{
			title = "Die Bedrohung aus der Tiefe",
			hint = [=[Erfahrt, was aus der Späherin wurde, die Burg Tiragarde beobachtete.]=],
			text = [=[Orgnil hatte eine Späherin der Zerschmetterten Hand abgestellt, um {link:tiragarde-keep}Burg Tiragarde{/link} zu beobachten. Als ihre Berichte ausblieben, fürchtete er Schlimmeres als {link:humans}Menschen{/link}. Er hatte recht. Das Banner und die zerbrochene Klinge, die man nahe ihrem Leichnam fand, gehörten den {link:naga}Naga{/link}, die von Norden die Küste herabgekommen waren. Orgnil befahl, die Naga zurückzutreiben und den jungen Meeresriesen zu erschlagen, der ihnen gefolgt war.]=],
		},
	},
	mentions = {
		{ text = "Bericht an Orgnil" },
		{ text = "Dunkle Stürme" },
		{ text = "{link:margoz}Margoz{/link}" },
		{ text = "Eine vermisste Hand" },
		{
			text = [=[Bedrohung aus der Tiefe, die Späher der {link:naga}Naga{/link}]=],
		},
		{ text = "Bedrohung aus der Tiefe, der Meeresriese" },
	},
	bonds = {
		{ id = "gar-thok", name = "Gar'Thok", note = "dient an seiner Seite" },
		{ id = "margoz", name = "Margoz", note = "ein Schamane, dem er vertraut" },
		{ id = "heglan-shadeeye", name = "Heglan Shadeeye", note = "seine verlorene Späherin" },
	},
})

