Translate("deDE", "zalazane", {
	title = "Zalazane",
	subtitle = "Hexendoktor der Echoinseln",
	found = "Die größte der Echoinseln",
	hint = "Stellt Euch dem Hexendoktor, der die Echoinseln beherrscht.",
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zalazane war einst ein Hexendoktor der {link:darkspear-trolls}Darkspear{/link}, ein begabter Schüler, der {link:master-gadrin}Meister Gadrin{/link} half, die Priester und Magier des Stammes auszubilden. Die Mächte, die er heraufbeschwor, trieben ihn in den Wahnsinn. Er verfluchte die Echoinseln, versklavte viele aus seinem eigenen Volk mit seinen Flüchen und trieb die übrigen über das Wasser aufs Festland. Nun herrscht er über die Inseln als ihr Herr, und er schickt seine verfluchten Diener über das Wasser, um seinen Fluch zu verbreiten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Zalazane ist der Grund, warum die {link:darkspear-trolls}Darkspear{/link} keine eigene Heimat haben. Jeder verfluchte Troll, der über seine Inseln wandert, ist eine Wunde im Herzen des Stammes.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versklavte die {link:trolls}Trolle{/link} der Echoinseln und trieb die freien {link:darkspear-trolls}Darkspear{/link} nach {link:sen-jin-village}Sen'jin{/link}.
• Er schickt seine verfluchten Trolle aufs Festland, um weitere ihrer Verwandten unter seinen Bann zu ziehen.
• Er bindet die Geister der Toten in Schädel und Bindungsanhänger.
• Er vergiftet den Fluss der Magie in {link:durotar}Durotar{/link} mit seinen Ju-Ju-Haufen.]=],
		},
	},
	chapters = {
		{
			title = "Der Schädelkreis",
			hint = [=[Holt den Schädel von Gadrins Bruder von Zalazanes Insel zurück.]=],
			text = [=[Auf der größten Insel unterhält Zalazane einen Kreis der Macht, umringt von den Schädeln der {link:trolls}Trolle{/link}, die er erschlagen hat. Ihre Geister können nicht fort. Unter ihnen war Minshina, der Bruder von {link:master-gadrin}Meister Gadrin{/link}, der in Träumen nach seinem Bruder rief, bis zu dem Tag, an dem sein Schädel heimgetragen wurde.]=],
		},
		{
			title = "Der Kopf des Fluchmeisters",
			hint = "Bringt Meister Gadrin den Kopf von Zalazane.",
			text = [=[Der Hexendoktor fiel zwischen seinen Hütten, und sein Kopf wurde nach {link:sen-jin-village}Sen'jin{/link} getragen. In jener Nacht schliefen die {link:trolls}Trolle{/link} des Dorfes in Frieden. Doch sein Fluch liegt noch immer auf den Inseln, und die {link:darkspear-trolls}Darkspear{/link} sind nicht in ihre Heimat zurückgekehrt.]=],
		},
	},
	mentions = {
		{ text = "Ju-Ju-Haufen" },
		{ text = "Eine Nervensäge, die Bindungsanhänger" },
		{ text = "Vergessene Loa-Götzen" },
	},
	bonds = {
		{ id = "master-gadrin", name = "Meister Gadrin", note = "sein einstiger Lehrer" },
		{ id = "vol-jin", name = "Vol'jin", note = "Häuptling des Stammes, den er verriet" },
	},
})

