Translate("deDE", "rezlak", {
	title = "Rezlak",
	subtitle = "Goblin der Karawanen",
	found = "Die Straße nördlich der Klingenschlucht",
	hint = [=[Sprecht mit dem Goblin, der an der Straße nach Orgrimmar auf seine Karawanen wartet.]=],
	allegiance = "Tinkers' Union · Ratchet",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rezlak ist einer der Goblins von {link:gazlowe}Gazlowe{/link}, dem Herrn von {link:ratchet}Ratchet{/link}, die geschickt wurden, um den {link:orcs}Orcs{/link} beim Bauen in {link:durotar}Durotar{/link} zu helfen. Seine Arbeit ginge gut voran, sagt er, wenn nur seine Karawanen ankämen. Die Staubwind-{link:harpies}Harpyien{/link} stehlen sie immer wieder. Rezlak zitiert bei jeder Gelegenheit die Sprüche seines Chefs, und er gedenkt, einem davon zu folgen: Wenn man etwas gut erledigt haben will, muss man es selbst tun und jemanden bezahlen, der hilft.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rezlak zeigt die Verbindung zwischen der {link:horde}Horde{/link} und den Goblins von {link:ratchet}Ratchet{/link}, die ihr Können gegen Gold tauschen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lässt sich seine gestohlenen Vorräte von den {link:harpies}Harpyien{/link} zurückholen.
• Er bezahlt dafür, die Harpyien aus der {link:drygulch-ravine}Staubwindklamm{/link} zu vertreiben.
• Er versucht, eine einer Harpyie abgenommene Sturmkugel mit den Organen von Donnerechsen neu aufzuladen.]=],
		},
	},
	mentions = {
		{ text = "Winde in der Wüste" },
		{ text = "Die Sicherung der Linien" },
		{ text = "Ein brodelnder Sturm" },
		{ text = "Stürmisches Potenzial" },
	},
})

Translate("deDE", "lieutenant-benedict", {
	title = "Leutnant Benedict",
	subtitle = "Befehlshaber von Burg Tiragarde",
