	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Leutnant Benedict führt die letzten Soldaten von Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} in {link:durotar}Durotar{/link}. Nach dem Tod des Admirals brachte er die Reserven von {link:kul-tiras}Kul Tiras{/link} zu den Ruinen von {link:tiragarde-keep}Burg Tiragarde{/link} zurück und befestigte sie. Er erkennt den Frieden nicht an, den {link:jaina-proudmoore}Jaina Proudmoore{/link} mit der {link:horde}Horde{/link} schloss. Er hält seinen Posten im Namen des Krieges eines toten Mannes.]=],
