})

Translate("deDE", "daelin-proudmoore", {
	title = "Daelin Proudmoore",
	subtitle = "Großadmiral von Kul Tiras",
	allegiance = "Kul Tiras · Haus Proudmoore",
	aliases = { "Daelin", "Admiral Proudmoore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Daelin Proudmoore war der Lordadmiral von {link:kul-tiras}Kul Tiras{/link} und der Vater von {link:jaina-proudmoore}Jaina Proudmoore{/link}. Im {link:second-war}Zweiten Krieg{/link} beherrschten seine Flotten die Meere für die {link:alliance}Allianz{/link}, und er wurde einer der großen Helden der Menschheit. Er vergab den {link:orcs}Orcs{/link} diesen Krieg nie. Als er erfuhr, dass sie sich an den Küsten von {link:kalimdor}Kalimdor{/link} niedergelassen hatten, kam er mit einer Armada, um sie zu vernichten, und er starb bei dem Versuch.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Daelins Krieg war die erste große Bedrohung für die junge Nation {link:durotar}Durotar{/link}. Sein Tod zog eine Linie zwischen Vater und Tochter und zwischen zwei Arten, die {link:orcs}Orcs{/link} zu sehen: als ein Volk, das sich ändern konnte, oder als Ungeheuer, die es nie tun würden. Seine Männer halten {link:tiragarde-keep}Burg Tiragarde{/link} noch immer in seinem Namen.]=],
		},
		{
			title = "Der Admiral der Allianz",
			text = [=[{link:kul-tiras}Kul Tiras{/link} war ein Königreich der Seeleute, und das Haus Proudmoore führte seine Flotten. Als die {link:horde}Horde{/link} nach dem {link:first-war}Ersten Krieg{/link} nach Norden zog, brachte Daelin seine Flotte in das Bündnis von {link:lordaeron}Lordaeron{/link} ein. Seine Schiffe bekämpften die Flotten der {link:orcs}Orcs{/link} auf offener See und trugen die Heere der {link:alliance}Allianz{/link} von Küste zu Küste. Kul Tiras zahlte einen hohen Preis an Schiffen und Männern. Daelin erinnerte sich sein Leben lang an diesen Preis.]=],
		},
		{
			title = "Die Armada",
			text = [=[Nach dem {link:third-war}Dritten Krieg{/link} führte seine Tochter {link:jaina-proudmoore}Jaina{/link} die Überlebenden Lordaerons nach Westen nach {link:kalimdor}Kalimdor{/link} und erbaute die {link:theramore-isle}Stadt Theramore{/link}. Dort schloss sie Frieden mit {link:thrall}Thrall{/link}. Daelin wollte ihn nicht anerkennen. Er segelte mit einer großen Flotte nach Kalimdor, errichtete {link:tiragarde-keep}Burg Tiragarde{/link} an der Küste Durotars und führte Krieg gegen die {link:orcs}Orcs{/link} und gegen die {link:trolls}Trolle{/link} der Echoinseln. Die {link:horde}Horde{/link} antwortete. Ihre Krieger brachen die Burg, und schließlich trugen sie den Kampf bis vor die Mauern von Theramore selbst. Jaina hielt sich abseits. In den Kämpfen wurde der Admiral erschlagen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligte im Zweiten Krieg die Flotte von {link:kul-tiras}Kul Tiras{/link}.
• Er errichtete {link:tiragarde-keep}Burg Tiragarde{/link} an den Küsten Durotars.
• Er führte Krieg gegen die {link:horde}Horde{/link}, dem Frieden seiner Tochter zum Trotz.
• Er hinterließ Befehle für einen Krieg, der nach seinem Tod weitergehen sollte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist hier über Daelins Leben vor den Kriegen geschrieben. Dieser Eintrag verzeichnet nur, was die Chroniken und seine eigenen Befehle verraten.]=],
		},
	},
	chapters = {
		{
			title = "Die Befehle des Admirals",
			hint = [=[Lest die versiegelten Befehle, die in Burg Tiragarde verwahrt werden.]=],
			text = [=[Unter den Habseligkeiten von {link:lieutenant-benedict}Leutnant Benedict{/link} lag ein alter Umschlag mit dem Siegel des Admirals. Er enthielt Befehle, die geschrieben worden waren, bevor Daelin {link:kul-tiras}Kul Tiras{/link} überhaupt verlassen hatte. Sie zeigten, dass er seine Pläne gut gefasst hatte und dass weitere seiner Männer der ersten Flotte nach {link:durotar}Durotar{/link} folgen sollten. Die {link:orcs}Orcs{/link} von {link:razor-hill}Klingenhügel{/link} lasen darin eine einfache Warnung: Der Admiral war tot, aber sein Krieg war es nicht.]=],
		},
	},
	mentions = {
		{ text = "Bezwingt die Verräter" },
		{
			text = [=[Die Befehle des Admirals, zu {link:gar-thok}Gar'Thok{/link} gebracht]=],
		},
		{
			text = [=[Die Befehle des Admirals, nach {link:orgrimmar}Orgrimmar{/link} gebracht]=],
		},
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "seine Tochter" },
		{ id = "lieutenant-benedict", name = "Leutnant Benedict", note = "führt seinen Krieg weiter" },
		{ id = "thrall", name = "Thrall", note = "sein Feind" },
	},
})
